# Generated by sync_menu_ui; edit canonical sources.
"""The settings a camera profile switched on holds (decisions of 2026-10-12, mockup profils/5_allume.png): greyed on
CAMERA VIEW and SHOULDER VIEW, with a line naming the profile and where to switch it off. A slider there would change
nothing the camera shows while the profile is on: visible and broken otherwise.

The rows are greyed after the menu's own greying by their switch (panel_form.refresh_dependency), the framing cards by
their own form (panel_framing_form.Form.enabled). Which settings a profile holds is panel_profile_window's OPTIONS and
FRAMING.
"""

from . import panel_profile_text as words, panel_text as tx, panel_theme as t, panel_widgets as w


def notice(rows, widgets, key):
    """The card's line naming the profile that holds its settings, collapsed while none does."""
    text = tx.text(rows, "", "status", wrap=True)
    text.SetVisibility(w.enum("ESlateVisibility", "Collapsed"))
    widgets[f"profile_notice:{key}"] = text
    w.column(rows, text, padding=w.pad(0, 0, t.SPACE_2))


def held(profiles):
    """The profile switched on, or None."""
    if profiles is None:
        return None
    store = profiles.ready()
    return None if store.active is None else store.profile(store.active)


def rows(widgets, profile):
    """Greys the rows of the settings the profile holds, each turn after the menu's own greying."""
    if profile is None:
        return
    from .panel_profile_window import OPTIONS
    for key in OPTIONS.values():
        if f"setting:{key}" in widgets:
            widgets[f"setting:{key}"].SetIsEnabled(False)
            for part in ("row", "description"):
                widgets[f"{part}:{key}"].SetRenderOpacity(t.OPACITY_DISABLED)


def notices(widgets, profile, language):
    """CAMERA VIEW's card names the profile over FOV and distances, each framing card it holds over its own."""
    from .panel_profile_window import FRAMING
    cards = (("camera", "profile_held_camera"), *((f"framing:{key}", "profile_held") for key in FRAMING.values()))
    for key, sentence in cards:
        name = f"profile_notice:{key}"
        if name not in widgets:
            continue
        text = ""
        if profile is not None:
            where = "profile_off_key" if profile.keyboard or profile.controller else "profile_off_page"
            text = (words.text(sentence, language).format(name=profile.name.upper()) + " "
                    + words.text(where, language))
        widgets[name].SetText(text)
        # A text's own visibility when shown: it never takes a click.
        shown = "Collapsed" if profile is None else "SelfHitTestInvisible"
        widgets[name].SetVisibility(w.enum("ESlateVisibility", shown))
